public class StatisticsEngine<T extends Number & Comparable<T>> {
    private final List<T> dataPoints;

    public StatisticsEngine(List<T> dataPoints) {
        this.dataPoints = dataPoints;
    }

    public double computeAverage() {
        double sum = 0.0;
        for (T number : dataPoints) {
            // Safe to call doubleValue() because 'Number' is an upper bound
            sum += number.doubleValue();
        }
        return dataPoints.isEmpty() ? 0.0 : sum / dataPoints.size();
    }
}
